solution_code:
function isAnagram(s, t) {
  if (s.length !== t.length) {
    return false;
  }
  const counts = new Map();
  for (const char of s) {
    counts.set(char, (counts.get(char) || 0) + 1);
  }
  for (const char of t) {
    if (!counts.has(char)) {
      return false;
    }
    const next = counts.get(char) - 1;
    if (next === 0) {
      counts.delete(char);
    } else {
      counts.set(char, next);
    }
  }
  return counts.size === 0;
}

