solution_code:
function isValid(s) {
  const pairs = new Map([[')', '('], [']', '['], ['}', '{']]);
  const stack = [];
  for (const char of s) {
    if (pairs.has(char)) {
      if (stack.pop() !== pairs.get(char)) {
        return false;
      }
    } else {
      stack.push(char);
    }
  }
  return stack.length === 0;
}

